+/// All-ones detector edge for `unary_iterate_log_star`: `gate ^= AND(gc)`.
+/// Uses a dirty-borrowed MCX (no fresh clean ancilla) when a valid `borrow`
+/// lender is supplied and the control count is in `mcx_dirty`'s supported
+/// range (3..=5); otherwise falls back to the clean-ancilla MCX.
+fn detector_mcx(circ: &mut Circuit, gc: &[&QReg], gate: &QReg, borrow: Option<&QReg>) {
+    if let Some(psi) = borrow {
+        let k = gc.len();
+        let lender_ok = !std::ptr::eq(psi, gate)
+            && !gc.iter().any(|&control| std::ptr::eq(psi, control));
+        if (3..=5).contains(&k) && lender_ok {
+            mcx_dirty(circ, gc, gate, psi);
+            return;
+        }
+    }
+    mcx_clean_k(circ, gc, gate);
+}

